  if (n === 0) return { text: 'Due today', late: true };
  if (n === 1) return { text: 'Due tomorrow', late: false };
  if (n <= 7) return { text: 'Due in ' + n + ' days', late: false };
  return { text: 'Due ' + fmtDay(d), late: false };
}
function ago(d) {
